58	/// The config files to layer, **lowest precedence first**.
59	///
60	/// `JJ_CONFIG` REPLACES the default locations rather than adding to them — that is jj's own
61	/// behaviour, and it is what makes the variable usable for isolation (the integration fixtures here
62	/// rely on it). It may name a file or a directory of `*.toml`.
63	///
64	/// Otherwise the two documented user locations are both collected, in the order jj's own precedence
65	/// implies. Merging them rather than picking one is a deliberate simplification: in practice exactly
66	/// one exists, and if somebody has both, honouring both in a defined order is friendlier than
67	/// silently ignoring whichever we didn't guess.
68	///
69	/// Verified against `jj config path --user` on macOS with jj 0.43 — it answers
70	/// `~/.config/jj/config.toml`, i.e. the XDG location, NOT `~/Library/Application Support`.
71	pub(crate) fn config_paths(env: &ConfigEnv) -> Vec<PathBuf> {
72	    if let Some(explicit) = &env.jj_config {
73	        return toml_files_at(explicit);
74	    }
75	    let mut paths = Vec::new();
76	    if let Some(home) = &env.home {
77	        paths.extend(toml_files_at(&home.join(".jjconfig.toml")));
78	    }
79	    let config_home = env
80	        .xdg_config_home
81	        .clone()
82	        .or_else(|| env.home.as_ref().map(|h| h.join(".config")));
83	    if let Some(dir) = config_home {
84	        paths.extend(toml_files_at(&dir.join("jj").join("config.toml")));
85	        // `conf.d` is jj's drop-in directory, layered above the single file.
86	        paths.extend(toml_files_at(&dir.join("jj").join("conf.d")));
87	    }
88	    paths
89	}
