91	/// The `*.toml` files at `path`: the file itself, or every `*.toml` directly inside it, sorted.
92	///
93	/// Sorted because a drop-in directory's precedence has to be reproducible — an unsorted `read_dir`
94	/// returns entries in filesystem order, so two machines with the same `conf.d` could resolve the
95	/// same key differently. Non-recursive, matching jj-lib's own (private) `load_from_dir`.
96	fn toml_files_at(path: &Path) -> Vec<PathBuf> {
97	    if path.is_file() {
98	        return vec![path.to_path_buf()];
99	    }
100	    if !path.is_dir() {
101	        return Vec::new();
102	    }
103	    let Ok(entries) = std::fs::read_dir(path) else {
104	        return Vec::new();
105	    };
106	    let mut files: Vec<PathBuf> = entries
107	        .filter_map(|entry| entry.ok().map(|e| e.path()))
108	        .filter(|p| p.is_file() && p.extension().is_some_and(|ext| ext == "toml"))
109	        .collect();
110	    files.sort();
111	    files
112	}
