114	/// jj's built-in defaults with the user's own configuration layered on top.
115	pub(crate) fn user_settings_for(env: &ConfigEnv) -> model::Result<UserSettings> {
116	    let mut config = StackedConfig::with_defaults();
117	    for path in config_paths(env) {
118	        // Skipped, not propagated — see the module comment. A broken config file costs the user
119	        // their settings, never their ability to read the repo.
120	        if let Ok(layer) = ConfigLayer::load_from_file(ConfigSource::User, path) {
121	            config.add_layer(layer);
122	        }
123	    }
124	    UserSettings::from_config(config).map_err(|e| VcsError::Io(e.to_string()))
125	}
