128	///
129	/// Deliberately NOT cached. The cost is a couple of small file reads per call, which is nothing
130	/// beside the tree snapshot they accompany, and caching would mean a user who fixes their
131	/// `user.email` has to relaunch the app before the app stops writing commits without one — which is
132	/// the exact failure this module exists to end.
133	pub(crate) fn user_settings() -> model::Result<UserSettings> {
134	    user_settings_for(&ConfigEnv::from_process())
135	}
