582	/// Snapshot the working copy so `@` reflects on-disk edits, returning the repo at the resulting
583	/// operation. Unlike the read-only `open`, this MUTATES (exactly like every `jj` command): it takes
584	/// the working-copy lock, and when disk differs from `@`'s tree it rewrites `@`, rebases descendants,
585	/// and commits a "snapshot working copy" operation. Modeled on jayjay's `refresh_working_copy`.
586	///
587	/// `base_ignores` chains the global + repo-local excludes (see `base_ignores`); `max_new_file_size`
588	/// matches the jj CLI default (1 MiB) so a status refresh can't hash/store an arbitrarily huge
589	/// untracked file.
590	fn snapshot_working_copy(root: &Path) -> model::Result<(Workspace, Arc<ReadonlyRepo>)> {
591	    let settings = crate::jj_config::user_settings()?;
592	    let mut workspace = Workspace::load(
593	        &settings,
594	        root,
595	        &StoreFactories::default(),
596	        &default_working_copy_factories(),
597	    )
598	    .map_err(workspace_load_err)?;
599	    let mut repo = pollster::block_on(workspace.repo_loader().load_at_head()).map_err(io)?;
600	
601	    let wc_name = workspace.workspace_name().to_owned();
602	    let Some(wc_commit_id) = repo.view().get_wc_commit_id(&wc_name).cloned() else {
603	        // No working-copy commit (e.g. a bare/foreign workspace) — nothing to snapshot.
604	        return Ok((workspace, repo));
605	    };
606	    let mut wc_commit = repo.store().get_commit(&wc_commit_id).map_err(io)?;
607	
608	    // Fail fast when someone else holds the working-copy lock (see `lock_is_held`) — a blocking
609	    // `flock` here would pin this thread, and a gate slot, for as long as the other process runs.
610	    if lock_is_held(&workspace) {
611	        return Err(VcsError::LockContention);
612	    }
613	
614	    let mut locked_ws = pollster::block_on(workspace.start_working_copy_mutation()).map_err(io)?;
615	
616	    // jj's own staleness guard, which every `jj` command runs and this read used to skip. The lock is
617	    // taken AFTER the repo was loaded, so between the two another process (the user's `jj` in a
618	    // terminal, or a sibling *workspace* of the same repo — i.e. another workroom — rewriting this
619	    // `@`) can have moved things underneath us. Snapshotting anyway would write a new `@` from a base
620	    // that no longer describes this working copy, which is how work gets clobbered.
621	    let freshness = pollster::block_on(WorkingCopyFreshness::check_stale(
622	        locked_ws.locked_wc(),
623	        &wc_commit,
624	        &repo,
625	    ))
626	    .map_err(io)?;
627	    match freshness {
628	        WorkingCopyFreshness::Fresh => {}
629	        // The working copy is AHEAD of the repo we loaded (something updated it in the gap). Not an
630	        // error — reload the repo at the working copy's own operation and carry on, exactly as the jj
631	        // CLI does, so a `jj` command racing the status sweep doesn't flash a failure in the sidebar.
632	        WorkingCopyFreshness::Updated(wc_operation) => {
633	            repo = pollster::block_on(repo.reload_at(&wc_operation)).map_err(io)?;
634	            let Some(id) = repo.view().get_wc_commit_id(&wc_name).cloned() else {
635	                drop(locked_ws); // release the lock before handing the workspace back
636	                return Ok((workspace, repo));
637	            };
638	            wc_commit = repo.store().get_commit(&id).map_err(io)?;
639	        }
640	        // Genuinely stale (`@` was rewritten/abandoned by another workspace) or divergent. Both are
641	        // `StaleSnapshot`: reporting a recoverable error beats snapshotting from a stale base. The
642	        // stale case is what `jj workspace update-stale` exists to repair — we deliberately don't run
643	        // it here, since recovering a working copy is a write the user hasn't asked for.
644	        WorkingCopyFreshness::WorkingCopyStale | WorkingCopyFreshness::SiblingOperation => {
645	            return Err(VcsError::StaleSnapshot);
646	        }
647	    }
648	
649	    let options = SnapshotOptions {
650	        base_ignores: base_ignores(root),
651	        progress: None,
652	        start_tracking_matcher: &EverythingMatcher,
653	        force_tracking_matcher: &NothingMatcher,
654	        max_new_file_size: 1024 * 1024, // 1 MiB — the jj CLI default (snapshot.max-new-file-size)
655	    };
656	    let (new_tree, _stats) =
657	        pollster::block_on(locked_ws.locked_wc().snapshot(&options)).map_err(io)?;
658	
659	    if new_tree.tree_ids_and_labels() != wc_commit.tree().tree_ids_and_labels() {
660	        // Disk changed since the last snapshot → rewrite `@` with the new tree + commit the op.
661	        let mut tx = repo.start_transaction();
662	        tx.set_is_snapshot(true);
663	        let write = tx
664	            .repo_mut()
665	            .rewrite_commit(&wc_commit)
666	            .set_tree(new_tree)
667	            .write();
668	        pollster::block_on(write).map_err(io)?;
669	        pollster::block_on(tx.repo_mut().rebase_descendants()).map_err(io)?;
670	        let new_repo = pollster::block_on(tx.commit("snapshot working copy")).map_err(io)?;
671	        pollster::block_on(locked_ws.finish(new_repo.op_id().clone())).map_err(io)?;
672	        Ok((workspace, new_repo))
673	    } else {
674	        // Clean — release the lock without rewriting `@`.
675	        pollster::block_on(locked_ws.finish(repo.op_id().clone())).map_err(io)?;
676	        Ok((workspace, repo))
677	    }
678	}
