680	/// The jj working-copy status: snapshot `@` (so it reflects disk), then read its change set, the
681	/// parent `@-` state, and the CI branch. `dirty` is set when `@` has changed files or a conflict.
682	/// (`insertions`/`deletions` come from this same read via `changed_files` — there is no second
683	/// `jj diff --stat` pass, Swift-side or otherwise.)
684	pub fn working_status(root: &Path) -> model::Result<model::WorkingStatus> {
685	    let (workspace, repo) = snapshot_working_copy(root)?;
686	    let store = repo.store();
687	    let bookmarks = bookmark_map(&repo);
688	    let Some(wc_id) = repo
689	        .view()
690	        .get_wc_commit_id(workspace.workspace_name())
691	        .cloned()
692	    else {
693	        return Ok(model::WorkingStatus {
694	            dirty: false,
695	            conflicted: false,
696	            working_copy: model::CommitChanges {
697	                change_id: None,
698	                commit_id: None,
699	                refs: Vec::new(),
700	                description: None,
701	                files: Vec::new(),
702	            },
703	            branch_for_ci: None,
704	        });
705	    };
706	    let wc_commit = store.get_commit(&wc_id).map_err(io)?;
707	    let conflicted = wc_commit.has_conflict();
708	    let wc_files = changed_files(store, &wc_commit)?;
709	    let working_copy = commit_changes(&wc_commit, wc_files, &bookmarks, repo.as_ref());
710	
711	    // NB: the parent `@-` change set is deliberately NOT computed — it would re-walk a second tree
712	    // diff on every status poll (fanned out per-workroom on a 15s sweep) for a disclosure group the
713	    // Changes panel no longer shows. If a parent view returns, compute it lazily on demand, not here.
714	    // Read this as "the branch History labels this workroom with", NOT "the branch nearest `@`" and
715	    // NOT "the branch this work will land on". It is the first bookmark in `::@` log order, which
716	    // down a merge's second parent can be strictly farther away in hops than a bookmark on `@`'s own
717	    // first parent (worked example in `first_bookmark_in_log_order`). Deliberately the very same call
