1	//! The snapshot must stamp the USER's identity onto `@`, not an empty one.
2	//!
3	//! `snapshot_working_copy` rewrites `@` whenever the working copy has moved, and jj-lib's
4	//! `CommitBuilder::for_rewrite_from` unconditionally sets `commit.committer = settings.signature()`.
5	//! While this crate built settings from `StackedConfig::with_defaults()` — whose compiled-in
6	//! `misc.toml` carries `user.name = ""` and `user.email = ""` — every status refresh that found a
7	//! change stamped an EMPTY committer onto the working-copy commit, for every jj user. Usually
8	//! invisible (`jj log` shows the author) and self-healing on the next real `jj` command, but not if
9	//! `@` is pushed as-is, which the app's Push button does via `jj git push --change @`.
10	//!
11	//! **This is its own test binary on purpose.** The fix reads `JJ_CONFIG` from the PROCESS
12	//! environment, so proving it end to end means setting that variable — and cargo runs the `#[test]`s
13	//! within a binary as parallel threads of one process, where a global env write would be visible to
14	//! and racing with every other test. One test, one binary, no race. The path policy itself is
15	//! covered deterministically by the unit tests in `src/jj_config.rs`, which take the environment as
16	//! a parameter and never touch the real one.
17	
18	use std::path::Path;
19	use std::path::PathBuf;
20	use std::process::Command;
21	
22	mod common;
23	
24	fn jj(args: &[&str], dir: &Path, config: &Path) -> std::process::Output {
25	    Command::new("jj")
26	        .args(args)
27	        .current_dir(dir)
28	        .env("JJ_CONFIG", config)
29	        .output()
30	        .unwrap_or_else(|e| panic!("run jj {args:?}: {e}"))
31	}
