33	/// A throwaway repo whose jj config names a distinctive identity.
34	fn init_repo(tag: &str) -> (PathBuf, PathBuf) {
35	    let dir = std::env::temp_dir().join(format!("wr-ident-{}-{}", std::process::id(), tag));
36	    let _ = std::fs::remove_dir_all(&dir);
37	    std::fs::create_dir_all(&dir).unwrap();
38	    let config = dir.join("jjconfig.toml");
39	    std::fs::write(
40	        &config,
41	        b"[user]\nname = \"Ada Lovelace\"\nemail = \"ada@example.com\"\n",
42	    )
43	    .unwrap();
44	    let init = jj(&["git", "init"], &dir, &config);
45	    assert!(
46	        init.status.success(),
47	        "jj git init: {}",
48	        String::from_utf8_lossy(&init.stderr)
49	    );
50	    (dir, config)
51	}
