53	/// `@`'s committer, as `name <email>`.
54	fn committer(dir: &Path, config: &Path) -> String {
55	    let out = jj(
56	        &[
57	            "log",
58	            "--ignore-working-copy",
59	            "--no-graph",
60	            "-r",
61	            "@",
62	            "-T",
63	            r#"committer.name() ++ " <" ++ committer.email() ++ ">""#,
64	        ],
65	        dir,
66	        config,
67	    );
68	    assert!(
69	        out.status.success(),
70	        "jj log: {}",
71	        String::from_utf8_lossy(&out.stderr)
72	    );
73	    String::from_utf8_lossy(&out.stdout).trim().to_string()
74	}
