76	#[test]
77	fn snapshot_stamps_the_users_identity_not_an_empty_one() {
78	    if common::skip_without(&["jj"], "committer identity test") {
79	        return;
80	    }
81	    let (dir, config) = init_repo("committer");
82	
83	    // The fix reads the process environment. Safe here because this binary holds exactly one test.
84	    std::env::set_var("JJ_CONFIG", &config);
85	
86	    // An on-disk edit jj hasn't snapshotted, so `working_status` must rewrite `@` to record it —
87	    // which is the rewrite that stamps the committer.
88	    std::fs::write(dir.join("a.txt"), b"hello\n").unwrap();
89	
90	    let status = wr_vcs_core::working_status(&dir).expect("working_status");
91	    assert!(
92	        !status.working_copy.files.is_empty(),
93	        "the snapshot should have picked up the on-disk edit"
94	    );
95	
96	    let stamped = committer(&dir, &config);
97	    assert_eq!(
98	        stamped, "Ada Lovelace <ada@example.com>",
99	        "the snapshot must carry the user's real identity; an empty one here is the bug this fixes"
100	    );
101	    assert!(
102	        !stamped.starts_with(" <"),
103	        "committer name must not be empty: {stamped}"
104	    );
105	
106	    std::env::remove_var("JJ_CONFIG");
107	    let _ = std::fs::remove_dir_all(&dir);
108	}
