91	    jj(&["commit", "-m", "base"], &dir, &cfg);
92	    let base = parent_id(&dir, &cfg);
93	    std::fs::write(dir.join("f.txt"), b"left\n").unwrap();
94	    jj(&["commit", "-m", "left"], &dir, &cfg);
95	    let left = parent_id(&dir, &cfg);
96	    jj(&["new", &base, "-m", "right"], &dir, &cfg);
97	    std::fs::write(dir.join("f.txt"), b"right\n").unwrap();
98	    jj(&["commit", "-m", "right"], &dir, &cfg);
99	    let right = parent_id(&dir, &cfg);
100	    jj(&["new", &left, &right], &dir, &cfg);
101	    (dir, cfg)
102	}
