370	        "an edited rename is still a rename; got {:?}",
371	        cs.files
372	    );
373	    assert_eq!(new.old_path.as_deref(), Some("old.txt"));
374	    assert!(
375	        !cs.files.iter().any(|f| f.path == "old.txt"),
376	        "no separate delete row; got {:?}",
377	        cs.files
378	    );
379	
380	    let _ = std::fs::remove_dir_all(&dir);
381	}
