383	/// Copy vs rename: when the source SURVIVES, the same copy record must classify as `Copied`, not
384	/// `Renamed` — the distinction jj-lib draws by checking whether the source is still present in the
385	/// target tree. The source is also modified on purpose: gix only looks for copy sources among
386	/// modified files (`CopySource::FromSetOfModifiedFiles`), so an untouched source yields no record at
387	/// all and the new file is a plain `Added`.
388	#[test]
389	fn a_surviving_source_is_copied_not_renamed() {
390	    if common::skip_without(&["jj"], "copy test") {
391	        return;
392	    }
393	    let (dir, cfg) = init_repo("copy");
394	    std::fs::write(dir.join("src.txt"), RENAME_BODY).unwrap();
395	    jj(&["commit", "-m", "add src.txt"], &dir, &cfg);
396	    std::fs::write(dir.join("dup.txt"), RENAME_BODY).unwrap();
397	    std::fs::write(
398	        dir.join("src.txt"),
399	        b"one\ntwo\nthree\nfour\nfive\nsix\nseven\nEDITED\n",
400	    )
401	    .unwrap();
402	
403	    let status = wr_vcs_core::working_status(&dir).expect("working_status");
404	    let files = &status.working_copy.files;
405	    let dup = files
406	        .iter()
407	        .find(|f| f.path == "dup.txt")
408	        .unwrap_or_else(|| panic!("dup.txt missing from {files:?}"));
409	    assert_eq!(
410	        dup.kind,
411	        wr_vcs_core::model::ChangeKind::Copied,
412	        "a copy whose source survives must not read as Renamed; got {files:?}"
413	    );
414	    assert_eq!(dup.old_path.as_deref(), Some("src.txt"));
415	    // The surviving source is still its own modification — a copy suppresses nothing.
416	    assert!(
417	        files
418	            .iter()
419	            .any(|f| f.path == "src.txt" && f.kind == wr_vcs_core::model::ChangeKind::Modified),
420	        "the copy source is still listed as Modified; got {files:?}"
421	    );
422	
423	    let _ = std::fs::remove_dir_all(&dir);
424	}
