426	/// A conflicted path is never ALSO a rename, which is worth pinning because it's the opposite of
427	/// what the classifier's branch order implies. Fixture: `base` has `old.txt`; `left` edits it in
428	/// place; `right` renames it to `new.txt` with a different edit. `@ = jj new left right` then holds a
429	/// delete/modify conflict on `old.txt` plus `new.txt`.
430	///
431	/// Observed (not assumed) result: `new.txt` is a plain `Added` with NO `old_path`, and `old.txt` is
432	/// `Conflicted` — no pairing. The reason is the backend: copy records come from the *git* tree of each
433	/// commit, and jj exports a conflicted commit as its `.jjconflict-base-N`/`.jjconflict-side-N` sidecar
434	/// trees, so gix's rewrite detection has no plain blob at the conflicted path to match against. The
435	/// `Conflicted`-before-rename branch in `changed_files` is therefore defensive ordering, not a case
436	/// this backend can currently reach — if a future jj-lib pairs them, this test flips and the branch
437	/// keeps the conflict badge instead of silently downgrading it to `Renamed`.
438	#[test]
439	fn a_conflicted_rename_does_not_pair_into_one_row() {
440	    if common::skip_without(&["jj"], "conflicted-rename test") {
441	        return;
442	    }
443	    let (dir, cfg) = init_repo("conflict-rename");
444	    std::fs::write(dir.join("old.txt"), RENAME_BODY).unwrap();
445	    jj(&["commit", "-m", "base"], &dir, &cfg);
446	    let base = parent_id(&dir, &cfg);
447	    // left: keep old.txt where it is, edit its last line.
448	    std::fs::write(
449	        dir.join("old.txt"),
450	        b"one\ntwo\nthree\nfour\nfive\nsix\nseven\nLEFT\n",
451	    )
452	    .unwrap();
453	    jj(&["commit", "-m", "left edits in place"], &dir, &cfg);
454	    let left = parent_id(&dir, &cfg);
455	    // right: rename it, with a conflicting edit on that same last line.
456	    jj(&["new", &base, "-m", "right renames"], &dir, &cfg);
457	    std::fs::remove_file(dir.join("old.txt")).unwrap();
458	    std::fs::write(
459	        dir.join("new.txt"),
460	        b"one\ntwo\nthree\nfour\nfive\nsix\nseven\nRIGHT\n",
461	    )
462	    .unwrap();
463	    jj(&["commit", "-m", "right renames"], &dir, &cfg);
464	    let right = parent_id(&dir, &cfg);
465	    jj(&["new", &left, &right], &dir, &cfg);
466	    assert!(
467	        jj_says_conflicted(&dir, &cfg),
468	        "fixture is not conflicted — the fixture is wrong, not the classifier"
469	    );
470	
471	    let status = wr_vcs_core::working_status(&dir).expect("working_status");
472	    let files = &status.working_copy.files;
473	    assert!(
474	        files
475	            .iter()
476	            .any(|f| f.path == "old.txt" && f.kind == wr_vcs_core::model::ChangeKind::Conflicted),
477	        "the conflicted path must still report the conflict; got {files:?}"
478	    );
479	    let new = files
480	        .iter()
481	        .find(|f| f.path == "new.txt")
482	        .unwrap_or_else(|| panic!("new.txt missing from {files:?}"));
483	    assert_eq!(
484	        new.kind,
485	        wr_vcs_core::model::ChangeKind::Added,
486	        "a conflict's sidecar trees defeat rename pairing; got {files:?}"
487	    );
488	    assert_eq!(
489	        new.old_path, None,
490	        "no copy record means no old path; got {files:?}"
491	    );
492	
493	    let _ = std::fs::remove_dir_all(&dir);
494	}
