496	#[test]
497	fn working_status_snapshots_disk_edits_without_corrupting() {
498	    if common::skip_without(&["jj"], "working_status test") {
499	        return;
500	    }
501	    let (dir, cfg) = init_repo("snapshot");
502	
503	    // Write a file on disk that jj has NOT snapshotted yet.
504	    std::fs::write(dir.join("hello.txt"), b"hi\n").unwrap();
505	
506	    // The read must snapshot `@` so the on-disk file shows up as a change.
507	    let status = wr_vcs_core::working_status(&dir).expect("working_status");
508	    assert!(status.dirty, "an on-disk edit should make @ dirty");
509	    assert!(
510	        status
511	            .working_copy
512	            .files
513	            .iter()
514	            .any(|f| f.path == "hello.txt"),
515	        "hello.txt should be a working-copy change; got {:?}",
516	        status.working_copy.files
517	    );
518	    assert!(!status.conflicted);
519	
520	    // No corruption: jj itself now sees the snapshotted file in @, and a second read agrees.
521	    let diff = jj(
522	        &[
523	            "diff",
524	            "--summary",
525	            "-r",
526	            "@",
527	            "--ignore-working-copy",
528	            "--color",
529	            "never",
530	        ],
531	        &dir,
532	        &cfg,
533	    );
534	    assert!(
535	        diff.status.success(),
536	        "jj diff after snapshot: {}",
537	        String::from_utf8_lossy(&diff.stderr)
538	    );
539	    assert!(
540	        String::from_utf8_lossy(&diff.stdout).contains("hello.txt"),
541	        "jj should see hello.txt in @ after our snapshot; got {:?}",
542	        String::from_utf8_lossy(&diff.stdout)
543	    );
544	    let status2 = wr_vcs_core::working_status(&dir).expect("second read");
545	    assert!(
546	        status2
547	            .working_copy
548	            .files
549	            .iter()
550	            .any(|f| f.path == "hello.txt"),
551	        "second read agrees"
552	    );
553	
554	    let _ = std::fs::remove_dir_all(&dir);
555	}
