557	/// The working copy's `change_id` is jj's SHORT display id: the reverse-hex ("z-k" digit) form
558	/// truncated to a unique prefix — the same thing `jj log` shows (e.g. `wo`), NOT the full 32-digit
559	/// hex. Guards the "use short refs for jj" behavior the Changes-panel header depends on.
560	#[test]
561	fn working_status_change_id_is_short_reverse_hex() {
562	    if common::skip_without(&["jj"], "change-id test") {
563	        return;
564	    }
565	    let (dir, cfg) = init_repo("change-id");
566	    // A couple of described commits so the repo isn't degenerate (a realistic unique prefix).
567	    std::fs::write(dir.join("a.txt"), b"a\n").unwrap();
568	    jj(&["commit", "-m", "first"], &dir, &cfg);
569	    std::fs::write(dir.join("b.txt"), b"b\n").unwrap();
570	
571	    let status = wr_vcs_core::working_status(&dir).expect("working_status");
572	    let cid = status.working_copy.change_id.expect("@ has a change-id");
573	
574	    // The full change-id jj prints for `@` (reverse-hex; no method → all 32 "digits").
575	    let full = jj(
576	        &[
577	            "log",
578	            "--no-graph",
579	            "--color",
580	            "never",
581	            "-r",
582	            "@",
583	            "-T",
584	            "change_id",
585	        ],
586	        &dir,
587	        &cfg,
588	    );
589	    let full = String::from_utf8_lossy(&full.stdout).trim().to_string();
590	
591	    assert!(!cid.is_empty(), "change-id is non-empty");
592	    assert!(
593	        cid.len() < full.len(),
594	        "short prefix ({cid:?}) shorter than full ({full:?})"
595	    );
596	    assert!(
597	        full.starts_with(&cid),
598	        "{cid:?} is a prefix of the full change-id {full:?}"
599	    );
600	    // Reverse-hex uses the letters k..=z only — never a 0-9a-f hex digit.
601	    assert!(
602	        cid.chars().all(|c| ('k'..='z').contains(&c)),
603	        "reverse-hex letters only; got {cid:?}"
604	    );
605	    // And it matches exactly what `jj log` shows as the short change-id.
606	    let short = jj(
607	        &[
608	            "log",
609	            "--no-graph",
610	            "--color",
611	            "never",
612	            "-r",
613	            "@",
614	            "-T",
615	            "change_id.shortest()",
616	        ],
617	        &dir,
618	        &cfg,
619	    );
620	    let short = String::from_utf8_lossy(&short.stdout).trim().to_string();
621	    assert_eq!(cid, short, "change-id matches jj's short change-id");
622	
623	    let _ = std::fs::remove_dir_all(&dir);
624	}
